function sanitizeUrl(url, options) {
    try {
        const result = new URL(String(url));
        result.username = '';
        result.password = '';
        if (false === options.path) {
            result.pathname = '/';
            if ('/' !== result.pathname) return;
        }
        if (!options.search) result.search = '';
        if (!options.hash) result.hash = '';
        return result.toString();
    } catch  {
        return;
    }
}
export { sanitizeUrl };
